import { post } from '@helpers/httpClient';

export interface IUploadBase64ResDTO {
  success: boolean;
  filename: string;
  name: string;
  extention: string;
  type: string;
  folder: string;
  url: string;
  sizes: { [key: string | number]: string };
}

export const uploadBase64Async = async (
  base64: any,
  { folder, name, sizes }: { folder?: string; name?: string; sizes?: number[] | string[] },
): Promise<{ src: string; res: IUploadBase64ResDTO }> => {
  try {
    const data: any = { folder, data: base64 };

    if (name?.length) {
      data.name = name;
    }

    if (sizes?.length) {
      data.sizes = sizes;
    }

    const res = await post('/ajax/saveBase64img.php', data);
    if (res?.success) {
      return Promise.resolve({
        src: `${res.url}`,
        res,
      });
    }
    return Promise.reject(
      new Error(res?.error || 'Что-то пошло не так при сохранении изображения'),
    );
  } catch (_e) {
    return Promise.reject(new Error('Не удалось сохранить изображение'));
  }
};

export async function deleteByUrlAsync(url: string) {
  try {
    const res = await post('/ajax/deleteFileByUrl.php', { url });
    if (res?.success) {
      return Promise.resolve(true);
    }
    return Promise.reject(new Error(res?.error || 'Что-то пошло не так при удалении изображения'));
  } catch (_e) {
    return Promise.reject(new Error('Не удалось удалить изображение'));
  }
}

export default {};
